#!/usr/bin/env python3
"""Generates supabase/content/batch_2a_draft.sql and docs/BATCH_2A_DOSSIERS_DRAFT.md from content/batch-2a.json (single source of truth)."""
import json
d=json.load(open('content/batch-2a.json')); S={s['id']:s for s in d['sources']}; SC={s['slug']:s for s in d['scholars']}
q=lambda v:"null" if v is None else "'"+str(v).replace("'","''")+"'"
lab=lambda l:l.lower().replace(' ','_')
loc=lambda cl:"; ".join(f"{x['id']} {x['locator']}" for x in cl['sources']) or "no source attached"
md=["# Batch 2A research dossiers (DRAFT, in review): al-Khwarizmi, Banu Musa, al-Kindi","",
"> **Status: draft.** Generated from `content/batch-2a.json`. Every claim has its own label. VERIFIED is used only where two independent academic sources that were actually read agree; most claims rest on one source and are ACADEMICALLY SUPPORTED. Locators are section- or entry-level (the sources have no stable page numbers). Nothing here has had human review.","",
"## Sources","","| ID | Source | Read? | Notes |","|---|---|---|---|"]
for s in d['sources']: md.append(f"| {s['id']} | {s['title']}{' (' + s['author'] + ')' if s['author'] else ''}, {s['publication']} | {'yes' if s['read'] else 'NO'} | {s['notes']} |")
for sc in d['scholars']:
    sl=sc['slug']; md+=["",f"## {sc['name_en']}","",f"*Kind:* {sc['kind']}. *Region:* {sc['region']}. *Dates:* {sc['dates']}. *Disciplines:* {', '.join(sc['disciplines']) or 'none established'}.",""]
    cl=[c for c in d['claims'] if c['scholar']==sl]
    if cl:
        md.append("### Claims ledger")
        for c in cl: md.append(f"- **{c['id']} [{c['label']}]** {c['text']}  \n  *Sources:* {loc(c)}."+(f" *Note:* {c['note']}" if c['note'] else "")+(f" *Needs:* {c['needs']}" if c['needs'] else ""))
    ws=[w for w in d['works'] if w['scholar']==sl]
    if ws:
        md+=["","### Works (original script titles not verified)","","| ID | Title as transcribed | Variants | Date | Status | Editions / manuscripts |","|---|---|---|---|---|---|"]
        for w in ws: md.append(f"| {w['id']} | {w['title']} | {', '.join(w['alt']) or '-'} | {w['year']} | {w['authorship_status']} | {w['notes']} {w['manuscripts']} |")
    cs=[c for c in d['contributions'] if c['scholar']==sl]
    if cs:
        md+=["","### Contributions (draft classification)",""]
        for c in cs: md.append(f"- **{c['title']}**: {c['kind']}, attribution confidence {c['confidence']}. *Before:* {c['prior']} *Contribution:* {c['detail']}")
    es=[e for e in d['events'] if e['scholar']==sl]
    if es:
        md+=["","### Timeline events",""]
        for e in es: md.append(f"- {e['year_earliest']}" + (f"–{e['year_latest']}" if e['year_latest']!=e['year_earliest'] else "") + f" ({e['date_certainty']}) **{e['title']}** [{e['label']}]: {loc(e)}")
rl=d['relationships']
if rl:
    md+=["","## Documented relationships",""]
    for r in rl: md.append(f"- **{r['id']}** {SC[r['scholar']]['name_en']} → {r['type']} → {SC[r['related']]['name_en']} [{r['label']}]; {loc(r)}")
md+=["","## Open research leads",""]+[f"{i+1}. {l}" for i,l in enumerate(d['leads'])]
md+=["","## What this batch does not claim","- No inventions or first-ever discoveries; no device-level Banu Musa claims; no individual attribution beyond what BEA states; no original-script titles; no exact dates where sources give approximate ones; no human-reviewed translations."]
open('docs/BATCH_2A_DOSSIERS_DRAFT.md','w').write("\n".join(md)+"\n")
L=["-- DRAFT CONTENT (generated by tools/build_batch.py). Loads as status 'draft'. Run once, after migrations and seed.sql.","-- Never visible to the public until it passes the publication gate (sources, approved independent review).","do $$ declare ids jsonb:='{}'; src jsonb:='{}'; sid uuid; wid uuid; eid uuid; rid uuid; srcid uuid; did int; begin"]
for sc in d['scholars']:
    L.append(f" insert into scholars(slug,region,period_group,dates_note,scholar_kind,status) values ({q(sc['slug'])},{q(sc['region'])},{q(sc['period'])},{q(sc['dates_note'])},{q(sc['kind'])},'draft') returning id into sid; ids:=ids||jsonb_build_object({q(sc['slug'])},sid);")
    L.append(f" insert into scholar_translations(scholar_id,lang,name) values (sid,'en',{q(sc['name_en'])});")
    for dn in sc['disciplines']: L.append(f" insert into scholar_disciplines(scholar_id,discipline_id) select sid,id from disciplines where name_en={q(dn)};")
for s in d['sources']:
    if s['read']: L.append(f" insert into sources(title,author,publication,url,source_type) values ({q(s['title'])},{q(s['author'])},{q(s['publication'])},{q(s['url'])},'academic') returning id into srcid; src:=src||jsonb_build_object({q(s['id'])},srcid);")
sidx=lambda sl:f"(ids->>{q(sl)})::uuid"; srcx=lambda i:f"(src->>{q(i)})::uuid"
for c in d['contributions']:
    L.append(f" select id into did from disciplines where name_en={q(c['discipline'])};")
    L.append(f" insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ({q(c['id'])},{sidx(c['scholar'])},{q(c['text'])},{q(c['title'])},'{c['kind']}','{c['confidence']}',did,{q(c['period'])},{q(c['prior'])},{q(c['detail'])},'under_review');")
    for r in c['refs']: L.append(f" insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ({q(c['id'])},{srcx(r['source'])},{q(r['locator'])},'academic_research');")
for w in d['works']:
    note=f"Date: {w['year']} ({w['yearSource']}). {w['notes']} Manuscripts: {w['manuscripts']}".strip()
    alts="array["+",".join(q(a) for a in w['alt'])+"]::text[]" if w['alt'] else "null"
    L.append(f" insert into works(scholar_id,original_title,alt_spellings,original_language,subject,authorship_status,publication_note) values ({sidx(w['scholar'])},{q(w['title'])},{alts},{q(w['language'])},{q(w['subject'])},'{w['authorship_status']}',{q(note)}) returning id into wid;")
    for r in w['sources']: L.append(f" insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,{srcx(r['id'])},{q(r['locator'])},'academic_research');")
for e in d['events']:
    L.append(f" insert into timeline_events(scholar_id,event_type,title,description,year_earliest,year_latest,date_certainty,date_note,confidence,label) values ({sidx(e['scholar'])},'{e['type']}',{q(e['title'])},{q(e['description'])},{e['year_earliest']},{e['year_latest']},'{e['date_certainty']}',{q(e['date_note'])},'{e['confidence']}','{lab(e['label'])}') returning id into eid;")
    for r in e['sources']: L.append(f" insert into claim_sources(timeline_event_id,source_id,locator,evidence_tier) values (eid,{srcx(r['id'])},{q(r['locator'])},'academic_research');")
for r in d['relationships']:
    L.append(f" insert into scholar_relationships(scholar_id,related_scholar_id,relation_type,description,confidence,label) values ({sidx(r['scholar'])},{sidx(r['related'])},'{r['type']}',{q(r['description'])},'{r['confidence']}','{lab(r['label'])}') returning id into rid;")
    for x in r['sources']: L.append(f" insert into claim_sources(relationship_id,source_id,locator,evidence_tier) values (rid,{srcx(x['id'])},{q(x['locator'])},'academic_research');")
L.append("end $$;")
open('supabase/content/batch_2a_draft.sql','w').write("\n".join(L)+"\n")
